    function geolocation_widget_flag(flag) {
        if (!flag) return '';

        var f = '';
        switch (flag) {
            case 'P': f = 'pioggia'; break;
            case 'T': f = 'temporale3'; break;
            case 'N': f = 'neve'; break;
            case 'M': f = 'pioggia_mista'; break;
            case 'F': f = 'nebbia'; break;
        }
        return f ? '<span class="s-small-container-flag" style="left: -2px;"><span class="s-small small-flag_' + f + '"></span></span>' : '';
    }
    function geolocation_widget_precip(p) {
        if (!p) return [false, false, false];

        const simbPioggia = "5,6,9,10,12,13,16,17,19,20".split(',');
        const simbNeve = "7,11,18".split(',');
        const flagPioggia = ['M', 'P', 'T'];
        const flagNebbia = 'F';
        const flagNeve = 'N';

        let mostraProvetta = false;
        let mostraFlag = false;
        let mostraFiocco = false;

        let flag = p.flag;
        let simbolo = p.simbolo;
        if (simbolo > 100) simbolo -= 100;

        // simbolo non piovoso e ho flag pioggia: provetta
        if (!simbPioggia.includes(simbolo) && flagPioggia.includes(flag)) {
            mostraProvetta = true;
            mostraFlag = true;
        }

        // simbolo non piovoso e ho flag neve: fiocco
        else if (!simbPioggia.includes(simbolo) && flag == flagNeve) {
            mostraFiocco = true;
            mostraFlag = true;
        }

        // simbolo piovoso: provetta senza flag
        else if (simbPioggia.includes(simbolo)) {
            mostraProvetta = true;
        }

        // simbolo neve: fiocco senza flag
        else if (simbNeve.includes(simbolo)) {
            mostraFiocco = true;
        }

        else if (flag) {
            mostraFlag = true;
        }

        return [mostraProvetta, mostraFlag, mostraFiocco];
    }
