	    {   /* gli oggetti google non sono ancora disponibili */
	        if(ilmeteo_dfp_reload.cont++ < 20)
	            setTimeout(function(){ilmeteo_dfp_reload(all)}, 250);  /* riprova poco dopo */
	        return;
	    }

	    if( all )
	    {
	        ilmeteo_dfp_create_query();
	        MNZ_reloadFull();
	    }
	    else
	    {
	        adv_advcount++;
	        ilmeteo_dfp_create_query();
