        function setDailyWeatherTime(t) {
                var type = $(".daily_forecast__general__menu__item--weather.daily_forecast__general__menu__item--active").length > 0 ? "" : "p";
                $(".daily_forecast__general__time__item").removeClass("daily_forecast__general__time__item--active");
                switch (t) {
                        case 'g':
                                $(".daily_forecast__map_container img").attr("src", $("#bigmap_image").attr("src"));
                                $(".daily_forecast__general__menu__item--rainfall").removeClass("daily_forecast__general__menu__item--active");
                                $(".daily_forecast__general__menu__item--weather").addClass("daily_forecast__general__menu__item--active");
                                break;
                        default:
                                $(".daily_forecast__map_container img").attr("src", $("#daily_map_" + t + type).attr("src"));
                                //$(".daily_forecast__general__menu__item--rainfall").show();
                                break;
                }
                $("#daily_forecast_general_time_" + t).addClass("daily_forecast__general__time__item--active");
                return false;
        }
        function setDailyWeatherType(t) {
                var time = $(".daily_forecast__general__time__item.daily_forecast__general__time__item--active").attr('id').replace("daily_forecast_general_time_", "");
                $(".daily_forecast__general__menu__item").removeClass("daily_forecast__general__menu__item--active");
                $(".daily_forecast__general__time__item").removeClass("daily_forecast__general__time__item--active");
                switch (t) {
                        case 'p':
                                $("#daily_forecast_general_time_g").hide();
                                if (time == 'g') time = 'm';
                                break;
                        default:
                                $("#daily_forecast_general_time_g").show();
                                break;
                }
                $("#daily_forecast_general_menu_" + t).addClass("daily_forecast__general__menu__item--active");
                $("#daily_forecast_general_time_" + time).addClass("daily_forecast__general__time__item--active");
                if (t == 'n') t = '';
                $(".daily_forecast__map_container img").attr("src", $("#daily_map" + (time == '' && t == '' ? '' : '_') + time + t).attr("src"));
                return false;
        }
